P.entries["item:a-clue-to-sanders-treasure"] = {n="Indizio per il Tesoro di Sanders",s="Nelle Marche Occidentali, l'Indizio per il Tesoro di Sanders porta chi cerca più avanti sulle tracce del Capitano Sanders. È la seconda tappa di una caccia tra le alture e le coste.",h="Nelle Marche Occidentali, l'Indizio per il Tesoro di Sanders porta chi cerca più avanti sulle tracce del...",kw={"barile","camino","indizio","pirata","sanders","tesoro","marche occidentali"},sec={{t="L'indovinello di un pirata",b="Dopo aver seguito la prima mappa del tesoro del Capitano Sanders, trovi una pergamena che indica la strada più all'interno delle Marche Occidentali. Il suo biglietto scarabocchiato ti manda verso est dalla costa e su per le scogliere, verso la strada principale.\n\nVicino a rovine di pietra cadenti e a un camino abbandonato, un vecchio barile segna il punto in cui Sanders ha nascosto l'indizio successivo. Le tracce conducono sempre più a fondo nelle campagne travagliate."}},faq={{q="Che cos'è questo indizio?",a="Il Capitano Sanders ha lasciato un biglietto scritto a mano per guidare chiunque sia abbastanza abile da seguire le sue tracce fino a un altro contenitore nascosto nelle Marche Occidentali.",al={"indizio di sanders","indizio per il tesoro di sanders","cos'è l'indizio per il tesoro di sanders"}},{q="Dove porta questo indizio?",a="L'indizio ti manda verso est dalla costa e su per le scogliere, verso la strada delle Marche Occidentali. Un vecchio barile si trova vicino a un camino in rovina.",al={"dove devo andare","destinazione dell'indizio","posizione del camino"}},{q="Chi era il Capitano Sanders?",a="Il Capitano Sanders era un pirata. La sua eredità sopravvive nei nascondigli del tesoro e negli indovinelli che sparse lungo le coste e le campagne delle Marche Occidentali.",al={"chi è il capitano sanders","storia di sanders","capitano sanders"}}},fx={e66b6229={q="Da dove viene questo indizio e chi l'ha scritto?",a="Questo biglietto fu lasciato dal Capitano Sanders, un famigerato spadaccino dei mari che seppellì il suo bottino illecito in giro per le Marche Occidentali. Invece di lasciare una mappa diretta del tesoro, l'astuto capitano scrisse una catena di indovinelli e indicazioni e nascose ogni messaggio in un punto riconoscibile della costa, per mettere alla prova chiunque fosse abbastanza audace o sveglio da seguirne le tracce.",al={"chi ha scritto l'indizio di sanders","da dove viene l'indizio","origine dell'indizio"}},["4dc920ed"]={q="Perché questo indizio è prezioso per chi cerca tesori?",a="Di per sé la pergamena è solo una filastrocca enigmatica, ma per chi sogna di fare fortuna è una tappa indispensabile per scoprire il leggendario nascondiglio del Capitano Sanders. Seguirne le indicazioni è l'unico modo per trovare la traccia successiva della sua elaborata caccia al tesoro e, alla fine, mettere le mani sulle ricchezze che il capitano pirata ha nascosto.",al={"perché volere l'indizio di sanders","perché l'indizio è importante","a cosa serve l'indizio di sanders"}}},fp="27,161,17.359.0,18.130.0,26.124.0,24.133.0"}
