P.entries["item:a-letter-to-grelin-whitebeard"] = {n="Lettera per Grelin Barbabianca",s="Una lettera da Forgiardente raggiunge Grelin Barbabianca nel suo accampamento nella Valle Crestafredda. Le sue notizie e istruzioni avvicinano la capitale montana alla frontiera innevata.",h="Una lettera da Forgiardente raggiunge Grelin Barbabianca nel suo accampamento nella Valle Crestafredda.",kw={"valle crestafredda","dun morogh","grelin barbabianca","forgiardente","lettera","consegna della posta"},ang={["race:Dwarf"]="Per chi appartiene al popolo dei nani, portare dispacci attraverso i gelidi passi di Dun Morogh è normale: i giovani montanari e le reclute lo fanno come compito fondamentale, sperando di farsi un nome."},sec={{t="Un dispaccio dalla montagna",b="Grelin Barbabianca riceve un dispaccio da Forgiardente nel suo accampamento nella Valle Crestafredda. Forgiamara offre riparo, ma la valle è lontana dalla sua sicurezza. Le lettere collegano gli esploratori e gli studiosi sul campo con le sale della capitale montana. Questa è arrivata a sud lungo i sentieri di montagna per raggiungerlo."}},faq={{q="Chi è Grelin Barbabianca?",a="Grelin Barbabianca è un esploratore nanico accampato nella parte sud-orientale della Valle Crestafredda. I messaggeri di Forgiamara gli portano notizie e istruzioni da Forgiardente.",al={"grelin barbabianca","chi è grelin","destinatario"}},{q="Da dove viene questa lettera?",a="La lettera proviene da Forgiardente, la capitale nanica. Un corriere postale locale la porta attraverso la Valle Crestafredda fino al campo.",al={"origine della lettera","chi ha spedito la lettera","da dove viene"}},{q="Che cosa contiene la lettera?",a="Re Magni Barbabronzea manda a Grelin un breve messaggio. Non ha tempo da perdere e gli concede di occuparsi dei troll come meglio crede, soprattutto se riesce a trovare una soluzione rapida. Grelin accoglie volentieri la notizia: era da tempo che non riceveva notizie da Forgiardente.",al={"contenuto della lettera","cosa dice","testo della lettera"}}},fx={["163f292d"]={q="Che cos'è la Lettera per Grelin Barbabianca?",a="È una missiva sigillata inviata da Forgiardente e portata giù attraverso la Valle Crestafredda, per essere consegnata a Grelin Barbabianca al suo accampamento lungo la strada.",al={"che cos'è la lettera di grelin barbabianca","lettera per grelin barbabianca","che lettera è questa"}},b0fcb20c={q="Perché Grelin Barbabianca vuole questa lettera?",a="Grelin è di stanza da tempo al suo accampamento nella Valle Crestafredda, senza notizie dalla capitale. Non vede l'ora di ricevere novità da Forgiardente.",al={"perché consegnare la lettera a grelin","perché grelin vuole la lettera","chi vuole la lettera di grelin"}}},fp="29,164,28.300.0,25.163.0,32.134.0,26.268.0"}
P.entries["item:a-mysterious-message"] = {n="Messaggio Misterioso",s="Nelle Marche Occidentali, il messaggio intercettato a un corriere fornisce alla Milizia del Popolo la prova di chi guida la Fratellanza dei Defias.",h="Nelle Marche Occidentali, il messaggio intercettato a un corriere fornisce alla Milizia del Popolo la prova...",kw={"unghianera","messaggero dei defias","edwin vancleef","gryan mantoforte","rivoluna","messaggio misterioso","marche occidentali"},ang={["class:Rogue"]="Il dispaccio intercettato offre ai ladri uno sguardo sulla sicurezza operativa, sui percorsi dei corrieri e sulle comunicazioni in codice usate dalla malavita dei Defias.",["faction:Alliance"]="Per chi combatte per l'Alleanza nelle Marche Occidentali, il documento intercettato dimostra che i disordini nelle campagne del regno sono un'insurrezione calcolata guidata da Edwin VanCleef, non semplice brigantaggio casuale."},sec={{t="Sussurri su Unghianera",b="Il dispaccio indica VanCleef come autorità della confraternita e nomina un complice chiamato \"Unghianera\". La rete più ampia resta nascosta. Decifrando il documento, la Milizia del Popolo ottiene un mezzo per far parlare i tagliaborse catturati e un modo per trovare la vera roccaforte della confraternita."},{t="Ordini intercettati",b="Un Messaggero dei Defias porta il messaggio tra le attività dei Defias a Rivoluna, alla Cava della Costa d'Oro e alla Miniera Venacava. Intercettarlo segna una svolta nelle indagini di Gryan Mantoforte. Per settimane la Milizia del Popolo aveva sospettato che qualcuno dirigesse la rivolta dei banditi, ma senza prove certe.\n\nLa missiva conferma che Edwin VanCleef comanda gli sforzi della confraternita in tutte le Marche Occidentali. Lo fa attraverso gradi in codice e intermediari."}},faq={{q="Che cosa rivela questo messaggio alla Milizia del Popolo?",a="Il messaggio fornisce a Gryan Mantoforte la prova che Edwin VanCleef dirige le operazioni della Fratellanza dei Defias in tutte le Marche Occidentali. Conferma i sospetti della milizia su chi comanda i fuorilegge.",al={"cosa dice il biglietto","storia del messaggio misterioso","cosa c'è nel messaggio"}},{q="Chi è Unghianera?",a="Unghianera è nominato nel testo intercettato come complice o agente. Poco altro si sa della sua identità o del luogo in cui si trova, il che ne fa una delle figure oscure che operano nel profondo della rete dei Defias.",al={"chi è unghianera","storia di unghianera","unghianera defias"}},{q="Chi porta questo messaggio?",a="Un Messaggero dei Defias porta il messaggio lungo le strade delle Marche Occidentali tra Rivoluna, la Cava della Costa d'Oro e la Miniera Venacava per coordinare le operazioni dei banditi.",al={"chi ha il messaggio","chi lascia cadere il messaggio misterioso","corriere dei defias"}},{q="Che cosa succede dopo che Gryan Mantoforte lo legge?",a="Confermato il ruolo di VanCleef, la milizia si concentra sulla ricerca del quartier generale dei Defias. Un ladro catturato accetta di guidare gli esploratori al nascondiglio segreto in cambio della vita.",al={"cosa succede dopo","reazione di mantoforte","dopo il messaggio misterioso"}}},fx={["9bec86bb"]={q="Che cos'è il Messaggio Misterioso?",a="È una lettera sigillata che un Messaggero dei Defias porta in giro per le Marche Occidentali. Indirizzata a un agente di nome Unghianera, contiene una corrispondenza cruciale tra i cospiratori che operano nella regione.",al={"messaggio misterioso","che messaggio è questo","biglietto dei defias"}},ea5b5889={q="Da dove viene il Messaggio Misterioso e chi l'ha scritto?",a="Il messaggio proviene dai ranghi più alti della Fratellanza dei Defias: fu scritto come istruzioni per il loro agente Unghianera e viaggia lungo il percorso dei corrieri che collega Rivoluna, la Cava della Costa d'Oro e la Miniera Venacava.",al={"chi ha scritto il messaggio misterioso","chi ha inviato il messaggio misterioso","origine del messaggio misterioso"}},f3ab4b79={q="Perché Gryan Mantoforte vuole il Messaggio Misterioso?",a="Gryan Mantoforte e la Milizia del Popolo vogliono a tutti i costi individuare il covo segreto della Fratellanza dei Defias e capirne la struttura di comando. Intercettare questa missiva fornisce loro la prova scritta e concreta che è Edwin VanCleef a orchestrare direttamente la ribellione della Fratellanza.",al={"perché volere il messaggio misterioso","perché mantoforte vuole il messaggio","perché procurarsi il messaggio misterioso"}}},fp="20,116,22.276.1,18.437.1,54.191.1,18.205.0,25.159.0,46.172.1"}
P.entries["item:a-simple-compass"] = {n="Bussola Semplice",s="Nella Cascina degli Alexston bruciata, nelle Marche Occidentali, la Bussola Semplice giace in una piccola cassa. Apparteneva a Baros Alexston prima che diventasse l'Architetto della Città di Roccavento.",h="Nella Cascina degli Alexston bruciata, nelle Marche Occidentali, la Bussola Semplice giace in una piccola...",kw={"alexston","baros","origini","cassa","bussola","cascina","roccavento","marche occidentali"},ang={["faction:Alliance"]="Aiutare Baros Alexston a recuperare il suo ricordo mostra il prezzo umano della rivolta dei Defias. Persino figure importanti di Roccavento hanno perso la casa di famiglia a causa dei disordini nelle Marche Occidentali.",["race:Human"]="Per chi è umano e appartiene al regno, la bussola racchiude un contrasto: i cortili sicuri e dorati di Roccavento e la frontiera abbandonata e senza legge delle Marche Occidentali."},sec={{t="Un ricordo d'infanzia",b="Baros Alexston crebbe lavorando nella fattoria di famiglia nelle Marche Occidentali. Il suo primo strumento per orientarsi fu una semplice bussola, che forse fece nascere il suo interesse per la geometria, il disegno tecnico e l'esplorazione. Poi la Fratellanza dei Defias assaltò e bruciò la cascina, e la bussola rimase in una robusta cassa tra le rovine mentre i banditi invadevano i campi."},{t="Un valore affettivo",b="Il padre di Baros sfuggì alla distruzione, ma non poté portare in salvo i beni di famiglia. Tra le mura di pietra di Roccavento la bussola serve a poco a un maestro costruttore, eppure per Baros conta molto. Restituirgliela gli ridarebbe un raro legame intatto con le sue umili origini e con le pacifiche campagne della sua infanzia."}},faq={{q="Che cos'è la Bussola Semplice?",a="Da ragazzo, nella fattoria di famiglia nelle Marche Occidentali, Baros Alexston possedeva la Bussola Semplice, una modesta bussola tascabile priva di magia.",al={"bussola semplice","bussola di alexston","bussola di baros"}},{q="Dove si trova la bussola?",a="La bussola è riposta nella Cassa di Alexston, tra le rovine bruciate della Cascina degli Alexston, appena a ovest di Guardiacolle nelle Marche Occidentali.",al={"dove trovare la bussola","posizione della bussola","posizione della cassa di alexston"}},{q="Chi vuole che la bussola venga restituita?",a="Baros Alexston, l'Architetto della Città di Roccavento, vuole riavere la bussola. Si trova vicino al municipio in Piazza della Cattedrale.",al={"chi ha bisogno della bussola","consegna della bussola","di chi è la bussola"}},{q="Perché la bussola è rimasta alla fattoria?",a="I fuorilegge Defias assaltarono e bruciarono la fattoria degli Alexston. Il padre di Baros fuggì per salvarsi la vita e non poté portare con sé i beni più pesanti, così la cassa rimase tra le macerie.",al={"perché hanno lasciato la bussola","cosa è successo alla fattoria"}}},fp="16,160,18.345.0,17.325.0,25.116.0,29.131.0,32.127.0,44.181.0"}
P.entries["item:a-stack-of-letters"] = {n="Catasta di Lettere",s="Nella Valle Crestafredda, una catasta di lettere è arrivata attraverso il passo montano per gli esploratori nelle terre selvagge innevate.",h="Nella Valle Crestafredda, una catasta di lettere è arrivata attraverso il passo montano per gli esploratori...",kw={"forgiamara","valle crestafredda","consegna della posta nella valle crestafredda","grelin barbabianca","catasta di lettere","talin occhioforte"},ang={["race:Dwarf"]="Per chi muove i primi passi da montanaro nella Valle Crestafredda, portare la posta tra gli accampamenti innevati è il primo incontro con le strade difficili di Dun Morogh e con le sue sentinelle sparse."},sec={{t="Attraverso il passo",b="Le lettere per la Valle Crestafredda arrivano da Forgiamara grazie ai viaggiatori che attraversano il passo. La strada fino agli accampamenti remoti tra le montagne di Dun Morogh è dura, quindi i portalettere si affidano ai viaggiatori per portare avanti ogni fascio. Questo è destinato agli esploratori più all'interno della Valle Crestafredda.\n\nFinché le lettere non vengono smistate, si pensa che l'unico destinatario sia Talin Occhioforte, nel suo accampamento in riva al lago. Tra queste c'è una missiva per il montanaro Grelin Barbabianca."}},faq={{q="Che cosa contiene la catasta di lettere?",a="Il fascio contiene lettere personali e dispacci per i nani della Valle Crestafredda. Si pensa che l'unico destinatario sia Talin Occhioforte, nel suo accampamento vicino al lago ghiacciato, finché tra le lettere non ne spunta una indirizzata a Grelin Barbabianca.",al={"cosa c'è nelle lettere","contenuto della catasta di lettere","per chi sono le lettere"}},{q="Chi manda queste lettere nella Valle Crestafredda?",a="Le lettere sono arrivate attraverso il passo nella Valle Crestafredda fino a Forgiamara. Da lì le ha portate avanti un viaggiatore disposto a consegnarle lungo la strada.",al={"da dove vengono le lettere","chi ha spedito le lettere"}},{q="Chi riceve le lettere?",a="L'esploratore nanico Talin Occhioforte riceve il pacco nel suo accampamento vicino al lago ghiacciato. Esaminando la catasta, trova una lettera per Grelin Barbabianca.",al={"chi riceve le lettere","destinatario della consegna"}}},fx={["6f17116a"]={q="Che cos'è la Catasta di Lettere?",a="È un fascio di posta arrivato nella Valle Crestafredda attraverso il passo di montagna. Affidata a te a Forgiamara, la catasta contiene la corrispondenza destinata ai montanari di stanza tra le nevi.",al={"che cos'è la catasta di lettere","oggetto catasta di lettere","che cosa sono le lettere"}},["9fce371d"]={q="Perché qualcuno vuole la Catasta di Lettere?",a="I montanari che vivono e pattugliano al freddo contano sulla posta regolare per tenersi informati. Talin Occhioforte aspetta questi dispacci da parecchio tempo presso il lago ghiacciato, anche se, a guardar bene, non tutte le lettere del fascio sono per lui.",al={"perché consegnare le lettere","perché talin vuole le lettere","scopo della catasta di lettere"}}},fp="18,110,16.437.0,36.225.0,44.154.0,25.149.0"}
