P.entries["item:alterac-granite"] = {n="Granito d'Alterac",s="Vicino alla Collina di Darrow, nel nord delle Alture di Colletorto, il Granito d'Alterac attira i maestri scalpellini per la sua resistenza e la sua grana. Il muratore reale di re Magni Barbabronzea vuole proprio questa pietra per un tributo ai soldati caduti.",h="Vicino alla Collina di Darrow, nel nord delle Alture di Colletorto, il Granito d'Alterac attira i maestri...",kw={"granito d'alterac","collina di darrow","colletorto","forgiardente","marmoduro","sully balloo","viadotto di thandol"},ang={["profession:Mining"]="Chi pratica l'estrazione mineraria o la prospezione sa apprezzare la frattura netta e la straordinaria densità del Granito d'Alterac, qualità che lo distinguono dalla comune roccia di montagna.",["race:Dwarf"]="Per chi appartiene al popolo dei nani, è chiaro perché gli scalpellini nanici tengano tanto alla qualità: questa robusta pietra di montagna onora un figlio di Forgiardente."},sec={{t="La pietra dei monumenti",b="Re Magni Barbabronzea ordinò un monumento a Sully Balloo, un coraggioso difensore nanico morto nella tragedia del Viadotto di Thandol. Il Gran Muratore Marmoduro ricevette l'incarico di scolpirlo a Forgiardente e pretese il Granito d'Alterac al posto della comune pietra di cava. Nei Regni Orientali poche pietre sono migliori, e la sua durevolezza conserva intatti l'effigie e il ricordo di un eroe caduto per generazioni."},{t="Estratto tra i pericoli",b="Il Granito d'Alterac si trova attorno alla Collina di Darrow, nel nord delle Alture di Colletorto, vicino ai territori in rovina di Alterac. Fauna ostile, briganti della Lega dei Tagliagole e conflitti mai sopiti rendono il viaggio pericoloso. Per portare lastre intatte agli artigiani di Forgiardente, devi spingerti in profondità in terre contese."}},faq={{q="A che cosa serve il Granito d'Alterac?",a="Il Gran Muratore Marmoduro di Forgiardente ha chiesto il Granito d'Alterac per un monumento reale a Sully Balloo, il soldato nanico caduto difendendo il Viadotto di Thandol.",al={"uso del granito d'alterac","perché il granito d'alterac","pietra di marmoduro"}},{q="Dove si trova il Granito d'Alterac?",a="Puoi raccogliere il Granito d'Alterac dai depositi della Collina di Darrow, nel nord delle Alture di Colletorto, vicino al confine con Alterac.",al={"posizione del granito d'alterac","dove trovare il granito d'alterac","granito della collina di darrow"}},{q="Perché il Gran Muratore Marmoduro voleva proprio questa pietra?",a="Il Gran Muratore Marmoduro considera il Granito d'Alterac una delle pietre da scultura migliori e più resistenti, degna del duraturo monumento reale commissionato da re Magni.",al={"perché marmoduro vuole il granito","perché la pietra d'alterac"}},{q="Chi era Sully Balloo?",a="Sully Balloo era un soldato nanico morto durante i combattimenti al Viadotto di Thandol. Re Magni Barbabronzea commissionò un monumento per onorare il suo sacrificio per l'Alleanza.",al={"sully balloo","chi è morto al viadotto di thandol"}}},fx={["9814170d"]={q="Che cos'è il Granito d'Alterac?",a="Il Granito d'Alterac è una pregiata pietra da cava di alta qualità, che si trova sulle colline del nord. Rinomato tra i maestri scalpellini come una delle migliori pietre da intaglio disponibili, ha la resistenza e la grana purissima necessarie per realizzare monumenti grandiosi e duraturi, degni delle commissioni reali.",al={"che cos'è il granito d'alterac","oggetto granito d'alterac","informazioni sul granito d'alterac"}},["842d3593"]={q="Da dove viene il Granito d'Alterac e chi lo produce?",a="Il Granito d'Alterac è una pietra naturale estratta dalla Collina di Darrow, sulle alture di Colletorto, al confine con le aspre montagne di Alterac. Non è fabbricato da alcun artigiano: viene tagliato direttamente dall'antica roccia delle colline, in attesa che muratori esperti lo trasformino in opere durature.",al={"origine del granito d'alterac","dove si estrae il granito d'alterac","chi produce il granito d'alterac"}}},fp="15,220,18.398.0,17.299.0,33.156.0,35.124.0,60.185.0,21.172.0"}
