P.entries["item:another-clue-to-sanders-treasure"] = {n="Altro Indizio per il Tesoro di Sanders",s="Nelle Marche Occidentali, un foglietto di pergamena del Capitano Sanders indica la strada verso il suo prossimo segnale nascosto.",h="Nelle Marche Occidentali, un foglietto di pergamena del Capitano Sanders indica la strada verso il suo...",kw={"scogliere","capitano sanders","indizio","pergamena","tesoro di sanders","marche occidentali","mulino a vento"},ang={["class:Rogue"]="Chi è ladro sa come leggere indicazioni criptiche e frugare in nascondigli dimenticati sulla costa in cerca di bottini nascosti."},sec={{t="Una pista sulle scogliere",b="Il Capitano Sanders nascose le sue ricchezze rubate in tutte le Marche Occidentali, lasciando indovinelli e segnali sepolti invece di un'unica mappa che potesse essere sequestrata. Questo foglietto porta avanti la pista dal nascondiglio precedente: dice di voltarsi a nord e cercare una brocca abbandonata accanto a un mulino a vento solitario, sopra le scogliere sul mare."}},faq={{q="Che cosa c'è scritto su questo indizio?",a="La pergamena dice di voltarsi verso nord dal barile nascosto e di camminare dritto fino a una brocca vuota accanto a un mulino a vento solitario sulle scogliere sul mare.",al={"cosa dice l'indizio","testo dell'indizio di sanders","indicazioni dell'indizio"}},{q="Chi era il Capitano Sanders?",a="Il Capitano Sanders era un pirata che lasciò nascondigli di bottino lungo le coste e le scogliere delle Marche Occidentali. Invece di lasciare una mappa intera, nascose segnali in tutta la regione.",al={"chi è sanders","passato del capitano sanders","sanders pirata delle marche occidentali"}},{q="Dove porta questo indizio?",a="L'indizio porta a nord lungo le scogliere costiere delle Marche Occidentali, fino a un mulino a vento solitario sulle rupi, dove una brocca vuota segna la tappa successiva della pista di Sanders.",al={"dove andare dopo","indizio del mulino di sanders","dov'è la brocca"}}},fx={b0e51eff={q="Che cos'è l'Altro Indizio per il Tesoro di Sanders?",a="È un pezzo di pergamena scritto a mano, scoperto in un vecchio barile lungo la costa delle Marche Occidentali. Il foglio riporta un'altra serie di indicazioni nautiche del Capitano Sanders, che guidano chiunque abbia il coraggio di seguirne le tracce verso il prossimo tassello nascosto del suo percorso.",al={"che cos'è l'altro indizio per il tesoro di sanders","pergamena con l'indizio di sanders","che pergamena con indizio è questa"}},["37a7a825"]={q="Da dove viene questo indizio e chi l'ha scritto?",a="L'indizio fu scritto e nascosto dal Capitano Sanders, un vecchio lupo di mare che lasciò una scia di indizi sparsi tra la costa e le campagne delle Marche Occidentali. Questo particolare pezzo di pergamena si recupera da un barile abbandonato, dove lo nascose molto tempo fa.",al={"chi ha scritto l'altro indizio per il tesoro di sanders","chi ha scritto l'indizio di sanders","da dove viene questo indizio"}},["632540c2"]={q="Perché qualcuno vuole l'Altro Indizio per il Tesoro di Sanders?",a="Seguire le tracce di Sanders è l'unico modo per scoprire il suo forziere sepolto. Ogni indizio si basa direttamente sul precedente e indica i punti di riferimento esatti per ripercorrere i passi del capitano nelle Marche Occidentali, fino alla fortuna che ha nascosto, qualunque essa sia.",al={"perché trovare l'indizio di sanders","perché voglio l'indizio del tesoro di sanders","a cosa serve l'indizio di sanders"}}},fp="33,88,29.292.0,29.131.0,24.163.0,31.145.0"}
