P.entries["item:bartleby-s-mug"] = {n="Boccale di Bartleby",s="A Roccavento, Burlguard chiede a chi si addestra da guerriero di conquistare il Boccale di Bartleby dal suo testardo proprietario. Bartleby lo cede solo dopo essere stato battuto in una rissa da taverna.",h="A Roccavento, Burlguard chiede a chi si addestra da guerriero di conquistare il Boccale di Bartleby dal suo...",kw={"bartleby","boccale di bartleby","burlguard","roccavento","rissa in taverna","addestramento da guerriero"},ang={["class:Warrior"]="Per chi è guerriero dell'Alleanza, il Boccale di Bartleby si conquista strappandolo a lui. Lo scontro richiede tenacia e forza quando le parole non bastano."},sec={{t="Il trofeo di un attaccabrighe",b="Bartleby si tiene stretto il suo amato boccale finché una rissa non lo mette al tappeto. Anche allora ne scola fino all'ultima goccia prima di consegnarlo. Il boccale dimostra che il guerriero ha saputo costringere un avversario poco collaborativo a cedere."}},faq={{q="A che cosa serve il Boccale di Bartleby?",a="Il Boccale di Bartleby è la prova della vittoria in una prova di addestramento per guerrieri. Portarlo all'istruttore dimostra che il guerriero ha saputo battere un testardo attaccabrighe da taverna e costringerlo a cedere il boccale.",al={"scopo del boccale di bartleby","perché mi serve il boccale di bartleby","cosa fa il boccale"}},{q="A chi appartiene in origine il boccale?",a="Il boccale appartiene a Bartleby, un ubriacone litigioso che passa il tempo a bere e a fare a pugni. Lo cede solo dopo che un aspirante guerriero lo ha battuto in una scazzottata, e solo dopo aver finito di bere.",al={"chi è bartleby","proprietario del boccale","chi ha il boccale"}},{q="Chi chiede il Boccale di Bartleby?",a="Il Boccale di Bartleby lo chiede Burlguard, l'addestratore dei guerrieri di Roccavento, che assiste alla rissa e vuole il boccale come prova prima di proseguire l'addestramento marziale.",al={"chi vuole il boccale","a chi do il boccale di bartleby","consegna del boccale di bartleby"}}},fx={["481c5411"]={q="Che cos'è il Boccale di Bartleby?",a="Il Boccale di Bartleby è il boccale personale di Bartleby, un attaccabrighe che frequenta le taverne di Roccavento. È la prova concreta del valore di un giovane guerriero: Bartleby lo cede solo dopo essere stato battuto per bene in combattimento, e solo dopo essersi preso il tempo di scolarne fino all'ultima goccia.",al={"che cos'è il boccale di bartleby","boccale di bartleby","il boccale di bartleby"}},a3659338={q="Perché Burlguard vuole il Boccale di Bartleby?",a="Burlguard esige il boccale come prova materiale che hai tenuto testa a Bartleby e l'hai sconfitto in una rissa da taverna. Portare via l'amato boccale a un bevitore incallito non è impresa da poco: se lo consegni, dimostri di aver convinto Bartleby a suon di pugni e di essere pronto a proseguire l'addestramento da guerriero.",al={"perché volere il boccale di bartleby","perché burlguard vuole il boccale","a cosa serve il boccale a burlguard"}}},fp="14,160,17.203.0,32.196.0,28.185.0,28.166.0"}
