P.entries["item:bloodstone-choker"] = {n="Girocollo con Sanguinite",s="A Roccavento, il Girocollo con Sanguinite di Gakin il Vincolaombre lega il rito di uno stregone al vuoto. La sua apprendista ha rubato il talismano ed è fuggita presso la Fratellanza dei Defias.",h="A Roccavento, il Girocollo con Sanguinite di Gakin il Vincolaombre lega il rito di uno stregone al vuoto.",kw={"girocollo con sanguinite","defias","gakin il vincolaombre","surena caledon","il vincolo","agnello macellato","ombra del vuoto","stregone"},ang={["class:Warlock"]="Per chi è stregone dell'Alleanza, recuperare il Girocollo con Sanguinite segna il passaggio dagli incantesimi di base al comando di formidabili servitori demoniaci.",["faction:Alliance"]="La fuga di Surena Caledon nella Fratellanza dei Defias mostra che i fuorilegge di Elwynn cercano pericolose reliquie occulte per rafforzare la loro ribellione contro Roccavento."},sec={{t="Un catalizzatore rubato",b="Il Girocollo con Sanguinite apparteneva un tempo a Gakin il Vincolaombre, maestro di stregoni sotto l'Agnello Macellato di Roccavento. La sua apprendista Surena Caledon lo ha tradito e lo ha rubato. È fuggita nelle foreste di Elwynn e si è unita alla Fratellanza dei Defias, portando con sé il talismano incantato. Ora si trova al Campo di Zucche dei Pozzonero. Il girocollo va recuperato prima che i banditi ne usino il potere."},{t="Domare il Vuoto",b="Intagliato nella sanguinite, il girocollo crea un ponte tra il mondo mortale e le ombre tortuose della Distorsione Fatua. Nelle cripte sotto la taverna, Gakin ne incanala la magia nel cerchio di evocazione, e un'Ombra del Vuoto ostile risponde dal vuoto. Uno stregone deve affrontare la creatura furiosa in combattimento diretto e sottometterla impugnando il talismano. Solo così dimostra la forza di volontà necessaria per comandare un simile guardiano."}},faq={{q="Che cos'è il Girocollo con Sanguinite?",a="Gli stregoni usano il Girocollo con Sanguinite, una collana incantata di sanguinite, come catalizzatore rituale. La sua magia può squarciare la realtà ed evocare un'indisciplinata Ombra del Vuoto dalla Distorsione.",al={"girocollo con sanguinite","cos'è il girocollo","cosa fa il girocollo"}},{q="A chi apparteneva in origine il girocollo?",a="Il primo proprietario del girocollo è stato Gakin il Vincolaombre, che addestra gli stregoni in un seminterrato segreto sotto l'Agnello Macellato, nel Quartiere dei Maghi di Roccavento.",al={"di chi è il girocollo","girocollo di gakin","da dove viene il girocollo"}},{q="Perché il girocollo è stato rubato?",a="Surena Caledon ha rubato il girocollo al suo mentore, Gakin, ed è fuggita per unirsi alla Fratellanza dei Defias. Cercava il potere tra i banditi nascosti nella Foresta di Elwynn.",al={"chi l'ha rubato","perché surena l'ha rubato","girocollo di surena caledon"}},{q="Come si usa il girocollo nell'addestramento degli stregoni?",a="Uno stregone attiva il girocollo recuperato sul cerchio di evocazione nelle cripte sotto l'Agnello Macellato. Il girocollo fa apparire un'Ombra del Vuoto, che l'aspirante stregone deve sconfiggere e sottomettere per comandare il demone.",al={"come usare il girocollo","rituale dell'ombra del vuoto girocollo","il girocollo del vincolo"}}},fx={["9d3659ea"]={q="Perché il Girocollo con Sanguinite è richiesto?",a="Gakin il Vincolaombre tiene al Girocollo con Sanguinite perché è un potente catalizzatore magico, necessario per evocare e vincolare un'ombra del vuoto. Dopo che la sua ex apprendista Surena Caledon lo rubò per aiutare la Fratellanza dei Defias, Gakin vuole riaverlo per ristabilire la propria autorità arcana e mettere alla prova i nuovi stregoni nelle cripte sotto l'Agnello Macellato.",al={"perché vogliono il girocollo con sanguinite","chi vuole il girocollo con sanguinite","perché gakin vuole il girocollo"}}},fp="17,164,16.382.1,15.394.0,30.174.0,32.144.0,26.157.0,43.209.0"}
