P.entries["item:book-stresses-of-iron"] = {n="Libro: Tensioni d'Acciaio",s="Al Forte di Roccavento, il libro di metallurgia di Margulf Blaggon è stato portato all'Abbazia della Contea del Nord per essere copiato.",h="Al Forte di Roccavento, il libro di metallurgia di Margulf Blaggon è stato portato all'Abbazia della Contea...",kw={"fratello kristoff","fratello paxton","margulf blaggon","metallurgia","milton sheaf","abbazia della contea del nord","biblioteca reale","tensioni d'acciaio"},ang={["profession:Blacksmithing"]="Il libro di Margulf Blaggon approfondisce la resistenza del ferro e i limiti pratici della sua lavorazione."},sec={{t="Un volume in prestito",b="Margulf Blaggon ha scritto di metallurgia, sia pratica sia teorica. Milton Sheaf custodiva il volume nella Biblioteca Reale del Forte di Roccavento. La biblioteca lo prestò all'Abbazia della Contea del Nord, dove Fratello Paxton lo copiò a mano per la propria raccolta. Il lavoro richiese molto più tempo del previsto, e così Fratello Kristoff, in Piazza della Cattedrale, attendeva con ansia il ritorno del libro in città."}},faq={{q="Di che cosa parla il libro?",a="Il libro di Margulf Blaggon tratta la metallurgia e la lavorazione dei metalli, in teoria e in pratica.",al={"cos'è tensioni d'acciaio","argomento di tensioni d'acciaio","contenuto del libro"}},{q="Perché il libro si trovava all'Abbazia della Contea del Nord?",a="Fratello Paxton prese in prestito il libro dalla Biblioteca Reale di Roccavento per copiarlo a mano per la propria raccolta. Poi doveva restituire l'originale.",al={"perché ce l'aveva paxton","perché nella contea del nord"}},{q="Chi voleva che il libro fosse restituito?",a="Fratello Kristoff voleva che il libro tornasse. Lo aspettava in Piazza della Cattedrale e lo chiedeva con urgenza. Un avventuriero lo rintracciò tra la Biblioteca Reale e la Contea del Nord.",al={"chi ha bisogno del libro","chi lo sta aspettando"}}},fx={["7d684098"]={q="Da dove viene Tensioni d'Acciaio e chi l'ha scritto?",a="Il libro fu scritto da Margulf Blaggon come trattato erudito di metallurgia. La sua sede è la Biblioteca Reale, all'interno del Forte di Roccavento, ma Fratello Paxton prese in prestito il volume e lo portò all'Abbazia della Contea del Nord per trascriverne con pazienza una copia per i propri scaffali.",al={"chi ha scritto tensioni d'acciaio","autore di tensioni d'acciaio","origine di tensioni d'acciaio"}}},fp="22,98,17.376.0,23.83.0,37.146.0,29.178.0"}
