P.entries["item:brock-s-list"] = {n="Elenco di Brock",s="A Thelsamar, Brock Scrutarocce manda un elenco degli allievi minatori premiati con picconi dalle sale della gilda di Forgiardente.",h="A Thelsamar, Brock Scrutarocce manda un elenco degli allievi minatori premiati con picconi dalle sale della...",kw={"elenco di brock","golnir granditone","grande forgia","forgiardente","loch modan","estrazione mineraria","thelsamar","thorgrum borrelson"},ang={["profession:Mining"]="Chi pratica la prospezione vede nell'Elenco di Brock un riconoscimento per gli apprendisti che si sono guadagnati un posto nelle tradizioni della Gilda Minatori della Montagna Profonda.",["race:Dwarf"]="Per chi appartiene al popolo dei nani, l'elenco onora i giovani minatori dediti al piccone e alla pala nelle profondità di Khaz Modan."},sec={{t="Un riconoscimento per minatori",b="A Khaz Modan, gli apprendisti devono dimostrare la loro abilità prima di affrontare un lavoro serio nelle miniere. Brock annota chi eccelle nelle lezioni e affida l'elenco ai viaggiatori diretti a Forgiardente, dove i nomi premiati possono essere incisi sui picconi."},{t="La strada verso la Grande Forgia",b="Un grifone porta l'Elenco di Brock dal posatoio di Thelsamar a Golnir Granditone, alla Gilda Minatori della Montagna Profonda nella Grande Forgia di Forgiardente. Lì i nomi degli studenti vengono incisi sui loro picconi d'onore."}},faq={{q="Che cos'è l'Elenco di Brock?",a="Brock Scrutarocce, l'addestratore minerario di Thelsamar, scrive un elenco degli apprendisti che eccellono nelle lezioni di estrazione mineraria e si guadagnano i picconi d'onore.",al={"elenco di brock","cos'è questo oggetto","scopo dell'elenco di brock"}},{q="A chi consegno l'Elenco di Brock?",a="Mostra l'Elenco di Brock a Thorgrum Borrelson, il maestro dei grifoni di Thelsamar, per ottenere il passaggio. Poi portalo a Golnir Granditone, alla Gilda Minatori della Montagna Profonda nella Grande Forgia di Forgiardente.",al={"dove porto l'elenco","chi riceve l'elenco di brock","consegna dell'elenco di brock"}},{q="Perché Golnir Granditone ha bisogno di questo documento?",a="Golnir Granditone sovrintende agli attrezzi della Gilda Minatori della Montagna Profonda a Forgiardente. Ha pronti i picconi d'onore e gli serve l'elenco di Brock per incidere su ognuno il nome di uno studente.",al={"perché golnir","perché forgiardente ha bisogno dell'elenco"}},{q="Perché l'elenco viene inviato in grifone e non a piedi?",a="I passi montani di Loch Modan collegano a Dun Morogh. Un grifone del posatoio di Thorgrum Borrelson porta l'elenco in modo rapido e sicuro fino alla Grande Forgia.",al={"perché volare a forgiardente","perché prendere un grifone"}}},fx={bca439a3={q="Da dove viene l'Elenco di Brock e chi l'ha scritto?",a="L'elenco è scritto da Brock Scrutarocce, un minatore veterano che lavora nel villaggio di Thelsamar, a Loch Modan. Man mano che i giovani nani passano da lui per imparare il mestiere, Brock ne valuta i progressi e compila questo elenco per registrare gli allievi eccezionali, che si sono guadagnati un riconoscimento speciale con il loro duro lavoro.",al={"chi ha scritto l'elenco di brock","da dove viene l'elenco di brock","autore dell'elenco di brock"}}},fp="12,110,21.250.0,27.201.0,21.139.0,33.190.0,46.171.0,49.159.0"}
