P.entries["item:bundle-of-wood"] = {n="Ciocco di Legno",s="Il Campo di Taglio di Vallevante ha bisogno di mandare legna verso ovest per la ricostruzione di Roccavento.",h="Il Campo di Taglio di Vallevante ha bisogno di mandare legna verso ovest per la ricostruzione di Roccavento.",kw={"ciocco di legno","vallevante","elwynn","campo di taglio","legname","raelen","tronchi"},ang={["faction:Alliance"]="Per chi viaggia con l'Alleanza, raccogliere i ciocchi aiuta la ricostruzione di Roccavento e fa arrivare in tempo le spedizioni vitali di legname agli insediamenti di Elwynn e delle Marche Occidentali."},sec={{t="Legname abbandonato",b="Il Campo di Taglio di Vallevante manda verso ovest legna appena tagliata per gli edifici e le altre costruzioni del Regno di Roccavento. Ma orsi e lupi sono entrati nei boschi a nord-ovest del campo. I taglialegna terrorizzati sono fuggiti, lasciando i loro Ciocchi di Legno tra gli alberi. Con la scadenza della spedizione ormai vicina, il sorvegliante Raelen ha bisogno di viaggiatori che recuperino il legname prima che i contratti vengano violati."}},faq={{q="Perché questi ciocchi di legno sono stati abbandonati nel bosco?",a="Lupi e orsi hanno messo in fuga i taglialegna che lavoravano a nord-ovest del Campo di Taglio di Vallevante. I lavoratori hanno lasciato i Ciocchi di Legno appena tagliati sul terreno della foresta.",al={"perché il legno è a terra","perché abbandonare il legno","legname abbandonato a elwynn"}},{q="Chi ha bisogno che questo legno venga raccolto?",a="Raelen, un sorvegliante del Campo di Taglio di Vallevante, ha bisogno che il legno venga raccolto presto per rispettare la scadenza di un'imminente spedizione di legname.",al={"chi vuole il legno","legname di raelen","consegna del legno"}},{q="Dove si trovano questi ciocchi?",a="I ciocchi si trovano tra gli alberi proprio a nord-ovest del Campo di Taglio di Vallevante, dove si aggirano gli orsi e i lupi di Elwynn.",al={"posizione del ciocco di legno","dov'è il legno","punti del legno a vallevante"}},{q="Perché le guardie del paese non hanno eliminato le bestie?",a="Raelen ha chiesto aiuto al Vicesceriffo Rainer, ma i marescialli e le guardie di Elwynn sono troppo pochi per tutta la regione. I taglialegna hanno bisogno di aiuto esterno per recuperare in fretta i tronchi.",al={"perché non ci sono guardie","vicesceriffo rainer legno","guardie a vallevante"}}},fx={e892b12c={q="Che cos'è un Ciocco di Legno?",a="Sono cataste di legname appena tagliato, raccolto dagli operai del Campo di Taglio di Vallevante. Pronte per il trasporto e la lavorazione, rappresentano l'attività di taglio che il campo porta avanti nella parte orientale della Foresta di Elwynn.",al={"che cos'è il ciocco di legno","ciocco di legno a elwynn","che cosa sono questi ciocchi di legno"}}},fp="14,70,16.390.0,54.168.0,30.123.0,30.115.0,48.173.0"}
