P.entries["item:burning-blood-quest-item"] = {n="Sangue Bruciante (oggetto di missione)",s="A Boscovespro, il sangue dei worgen Cuparovina attira l'interesse di Grimand Elmore. Gli servono venti fiale per i suoi esperimenti di forgiatura.",h="A Boscovespro, il sangue dei worgen Cuparovina attira l'interesse di Grimand Elmore.",kw={"sangue bruciante","boscovespro","furen barbalunga","grimand elmore","spillabudella","cuparovina","rovina di roland","worgen"},ang={["class:Warrior"]="Grimand Elmore usa il Sangue Bruciante per mettere alla prova metodi di forgiatura. Promette resistenti armature a piastre ai guerrieri che glielo portano.",["profession:Blacksmithing"]="Chi lavora come fabbro può usare materiali insoliti come il sangue bruciante dei worgen per temprare metalli pesanti a temperature estreme."},sec={{t="Un reagente instabile",b="I worgen Cuparovina si aggirano per Boscovespro in preda a una strana furia, e il loro sangue brucia davvero. Si può ricavare dai worgen che infestano i boschi e la Rovina di Roland. Gli armaioli ne cercano il calore per temprare piastre resistenti."},{t="L'esperimento di Elmore",b="Grimand Elmore è un armaiolo del Distretto dei Nani di Roccavento. Vuole mettere alla prova metodi di forgiatura ideati dal suo ex allievo Furen Barbalunga.\n\nPer l'esperimento, Elmore ha bisogno del Sangue Bruciante e di una densa roccia ardente in possesso del capo dei worgen Spillabudella. A chi gli porta il liquido ribollente promette una robusta armatura da guerriero uscita dalla sua forgia."}},faq={{q="Che cos'è il Sangue Bruciante?",a="I worgen Cuparovina di Boscovespro hanno il sangue rovente. A Grimand Elmore serve per i suoi esperimenti di forgiatura.",al={"storia del sangue bruciante","cos'è il sangue bruciante","sangue di worgen"}},{q="Da dove viene il Sangue Bruciante?",a="Il Sangue Bruciante proviene dai worgen Cuparovina di Boscovespro, soprattutto da quelli attorno alla Rovina di Roland.",al={"dove ottenere il sangue bruciante","chi lascia cadere il sangue bruciante","posizione del sangue bruciante"}},{q="Perché Grimand Elmore ne ha bisogno?",a="A Grimand Elmore serve il Sangue Bruciante per mettere alla prova i metodi di forgiatura sviluppati da Furen Barbalunga. Con una roccia ardente, intende forgiare una cotta protettiva per un guerriero.",al={"perché grimand vuole il sangue bruciante","missione del sangue di grimand elmore"}},{q="Perché il sangue dei Cuparovina brucia?",a="I Cuparovina sono creature innaturali evocate da magie oscure e caotiche. La maledizione nel loro sangue gli dà un calore feroce e innaturale.",al={"perché i worgen hanno sangue bruciante","il sangue dei worgen è fuoco"}}},fp="26,119,18.206.0,19.337.0,22.94.0,35.93.0,32.159.0,42.123.0"}
P.entries["item:burning-rock"] = {n="Roccia Ardente",s="A Boscovespro, la Roccia Ardente fuma nella Rovina di Roland. La porta Spillabudella, capo dei worgen Cuparovina, e a Grimand Elmore di Roccavento serve insieme all'infuocato sangue dei worgen per forgiare armature incantate per guerrieri promettenti.",h="A Boscovespro, la Roccia Ardente fuma nella Rovina di Roland.",kw={"roccia ardente","boscovespro","furen barbalunga","grimand elmore","spillabudella","worgen cuparovina","rovina di roland"},ang={["class:Warrior"]="Per chi è guerriero, è l'occasione di sfidare la Rovina di Roland per la Roccia Ardente. Grimand Elmore ricompensa il tuo valore con un'armatura su misura forgiata grazie al suo calore.",["profession:Blacksmithing"]="Chi lavora come fabbro può studiare la Roccia Ardente come fonte di calore insolita. Gli armaioli di Roccavento e di Forgiardente esplorano metodi non convenzionali per fondere e temprare le armature."},sec={{t="Un premio fumante",b="Spillabudella porta la Roccia Ardente nei pozzi della Rovina di Roland. Grimand Elmore, a Roccavento, ne vuole il calore per un'armatura fatta con l'infuocato sangue dei worgen. Sta mettendo alla prova tecniche di forgiatura sviluppate dal suo collega Furen Barbalunga, sperando di ottenere piastre resistenti per combattenti veterani."}},faq={{q="Dove si trova la Roccia Ardente?",a="Spillabudella porta la Roccia Ardente nella Rovina di Roland, nel Boscovespro orientale.",al={"posizione della roccia ardente","chi lascia cadere la roccia ardente","dove ottenere la roccia ardente"}},{q="Chi vuole la Roccia Ardente?",a="Grimand Elmore, un fabbro nanico del Distretto dei Nani di Roccavento, vuole la Roccia Ardente per mettere alla prova tecniche di forgiatura sperimentali.",al={"chi ha bisogno della roccia ardente","a chi si consegna la roccia ardente","grimand elmore roccia ardente"}},{q="Perché Grimand Elmore ne ha bisogno?",a="Grimand vuole mettere alla prova le tecniche di forgiatura sviluppate da Furen Barbalunga. Insieme al sangue dei worgen Cuparovina, la roccia fumante fornisce il calore per forgiare un'armatura unica.",al={"uso della roccia ardente","perché la roccia ardente","cosa fa la roccia ardente"}},{q="Che legame ha questa roccia con i worgen?",a="I worgen Cuparovina della Rovina di Roland hanno strane caratteristiche infuocate, come il sangue bruciante. Il loro capo, Spillabudella, tiene la Roccia Ardente nelle profondità della miniera. Non si sa come ci sia arrivata.",al={"perché i worgen hanno la roccia ardente","storia della roccia ardente di spillabudella"}}},fx={a40de154={q="Che cos'è la Roccia Ardente?",a="La Roccia Ardente è un minerale raro e incandescente, che si trova nel profondo dei boschi infestati di Boscovespro. In possesso di Spillabudella, il capo dei feroci worgen Cuparovina che occupano la Rovina di Roland, questa pietra infuocata conserva un calore intenso ed è ricercata per lavori specializzati di forgiatura e metallurgia.",al={"che cos'è la roccia ardente","oggetto roccia ardente","notizie sulla roccia ardente"}}},fp="12,224,18.267.0,32.71.0,27.130.0,32.170.0,50.186.0"}
